using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Net;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.IO.Compression;
using kok;
class ContentServicesTests {
 sealed class EmbedFixture:HttpMessageHandler {
  internal static int calls;
  protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){calls++;var value=Library.Json.Deserialize<Dictionary<string,object>>(await request.Content.ReadAsStringAsync());var inputs=AgentTaskState.Get<List<string>>(value,"input");var vectors=inputs.Select(s=>s.Contains("咖啡")||s.Contains("espresso")||s.Contains("提神饮品")?new[]{0d,1,0}:s.Contains("相机")||s.Contains("摄影")?new[]{1d,0,0}:new[]{0d,0,1}).ToArray();return new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(Library.Json.Serialize(new{embeddings=vectors}),Encoding.UTF8,"application/json")};}
 }
 static void Reject(Action action,Action<bool,string> check,string message){bool bad=false;try{action();}catch{bad=true;}check(bad,message);}
 public static void Run(string root,Action<bool,string> check){
  var lib=new Library(Path.Combine(root,"data"));lib.SetAppMode("smart",true);Entry camera=lib.CreateDocument("摄影清单","md","Travel","相机和备用电池，出门前充满电。"),coffee=lib.CreateDocument("手冲步骤","md","Kitchen","咖啡：先烧水，再慢慢注水萃取。"),outside=lib.CreateDocument("Outside","md","Other","PRIVATE_OUTSIDE_CANARY");
  foreach(var item in lib.ContentEntries())lib.IndexContentSource(item.id);check(lib.ContentStatus().All(s=>s.state=="ready"&&s.chunks>0),"content index records extraction coverage and bounded chunks");
  var clip=new ClipRecord{id=Guid.NewGuid().ToString("N"),title="独立摘录",text="CLIP_SEARCH_CANARY",created=DateTime.UtcNow.ToString("o"),source=new SourceAnchor{itemId=camera.id,chapter=0,start=2,end=8,text="备用电池"}};var op=lib.ProposeResource("clip",clip.id,Library.Json.Serialize(clip));new Operations(lib,null).Apply(op.id);lib.IndexContentSource(camera.id);check(lib.FullTextSearch("CLIP_SEARCH_CANARY").Contains(camera.id),"independent saved Clips participate in full text retrieval");
  var chunk=lib.ReadContentChunks(new[]{camera.id}).First(c=>c.kind=="clip");check(chunk.anchor.itemId==camera.id&&chunk.anchor.start==2&&chunk.clipId==clip.id,"indexed Clips retain their original source anchor and identity");
  lib.Update(camera.id,new Dictionary<string,object>{{"notes","New note invalidates cached chunks"}});Reject(()=>lib.ReadContentChunk(chunk.id,new[]{camera.id}),check,"source edits invalidate prior indexed excerpts before they can be read");check(!lib.FullTextSearch("CLIP_SEARCH_CANARY").Contains(camera.id),"stale extracted text is removed from lexical results until rebuilding");lib.IndexContentSource(camera.id);
  var embedder=new LocalEmbedder(()=>new EmbedFixture());lib.SaveEmbeddingConfig(new EmbeddingConfig{enabled=true,model="fixture",minimumSimilarity=.5});lib.BuildEmbeddings(CancellationToken.None,null,embedder).GetAwaiter().GetResult();int calls=EmbedFixture.calls;lib.BuildEmbeddings(CancellationToken.None,null,embedder).GetAwaiter().GetResult();check(calls==EmbedFixture.calls,"unchanged source chunks reuse embeddings without extra requests");
  var found=lib.SearchKnowledge("提神饮品",new[]{camera.id,coffee.id},"hybrid",10,CancellationToken.None,embedder).GetAwaiter().GetResult();check(found.ids.Contains(coffee.id)&&!found.ids.Contains(outside.id),"hybrid retrieval uses embedding results within the explicit source scope");
  var scoped=lib.SearchKnowledge("PRIVATE_OUTSIDE_CANARY",new[]{camera.id},"lexical",10,CancellationToken.None).GetAwaiter().GetResult();check(scoped.ids.Count==0,"lexical fallback cannot expose an out-of-scope source");
  Reject(()=>LocalEmbedder.Endpoint("https://example.com/api/embed"),check,"embedding endpoints reject remote hosts");Reject(()=>LocalEmbedder.Normalize(new[]{Double.NaN,1}),check,"embedding responses reject invalid numbers");Reject(()=>LocalEmbedder.Normalize(new[]{0d,0}),check,"zero-length embedding vectors are rejected");
  lib.SaveEmbeddingConfig(new EmbeddingConfig{enabled=true,model="fixture",revision="2"});var changed=lib.SearchKnowledge("提神饮品",new[]{coffee.id},"semantic",10,CancellationToken.None,embedder).GetAwaiter().GetResult();check(changed.mode=="lexical"&&changed.notice!="","model revisions prevent reuse of incompatible vectors and expose fallback");
  lib.SetAppMode("pure",false);calls=EmbedFixture.calls;Reject(()=>lib.SearchKnowledge("提神饮品",new[]{coffee.id},"hybrid",10,CancellationToken.None,embedder).GetAwaiter().GetResult(),check,"Pure mode refuses semantic requests before contacting a model");check(calls==EmbedFixture.calls,"Pure mode sends no local embedding request");lib.SetAppMode("smart",true);
  string pdf=Path.Combine(root,"pages.pdf");File.WriteAllText(pdf,"PDF fixture extraction is supplied by the renderer");lib.Import(new[]{pdf},null);var pdfItem=lib.Db.items.First(e=>e.path==pdf);lib.IndexContentSource(pdfItem.id,new List<ContentPage>{new ContentPage{page=3,text="PAGE_THREE_CANARY"}});var pageChunk=lib.ReadContentChunks(new[]{pdfItem.id}).First(c=>c.kind=="page");check(pageChunk.anchor.page==3&&lib.FullTextSearch("PAGE_THREE_CANARY").Contains(pdfItem.id),"PDF text-layer results preserve page numbers and enter the content index");
  var space=new SpaceRecord{id=Guid.NewGuid().ToString("N"),name="Portable",members=new List<string>{camera.id,clip.id}};new Operations(lib,null).Apply(lib.ProposeResource("space",space.id,Library.Json.Serialize(space)).id);
  string archive=Path.Combine(root,"library.koklib");lib.ExportKnowledge(archive,true,CancellationToken.None);using(var zip=ZipFile.OpenRead(archive))using(var reader=new StreamReader(zip.GetEntry("manifest.json").Open())){string manifest=reader.ReadToEnd();var portable=Library.Json.Deserialize<PortableLibrary>(manifest);check(portable.version==2&&portable.items.All(e=>!Path.IsPathRooted(e.path))&&!manifest.Contains(root.Replace("\\","\\\\")),"portable v2 manifests do not export local absolute source paths");}
  string refs=Path.Combine(root,"references.koklib");lib.ExportKnowledge(refs,false,CancellationToken.None);using(var zip=ZipFile.OpenRead(refs))using(var reader=new StreamReader(zip.GetEntry("manifest.json").Open())){var data=Library.Json.Deserialize<PortableLibrary>(reader.ReadToEnd());check(data.items.Single(e=>e.id==pdfItem.id).path=="pages.pdf","external references default to filenames without disclosing parent directories");}
  string referenceTarget=Path.Combine(root,"reference-restored");lib.RestoreKnowledge(refs,referenceTarget,"",root,CancellationToken.None);check(new Library(referenceTarget).Find(pdfItem.id).path==pdf,"v2 external references map against an explicit new root without the old absolute root");
  string legacy=Path.Combine(root,"legacy-v1.koklib");using(var input=ZipFile.OpenRead(refs))using(var output=ZipFile.Open(legacy,ZipArchiveMode.Create)){foreach(var entry in input.Entries){using(var stream=output.CreateEntry(entry.FullName).Open()){if(entry.FullName=="manifest.json"){PortableLibrary data;using(var r=new StreamReader(entry.Open()))data=Library.Json.Deserialize<PortableLibrary>(r.ReadToEnd());data.version=1;data.items.First(e=>e.id==pdfItem.id).path=pdf;var bytes=Encoding.UTF8.GetBytes(Library.Json.Serialize(data));stream.Write(bytes,0,bytes.Length);}else using(var source=entry.Open())source.CopyTo(stream);}}}string legacyTarget=Path.Combine(root,"legacy-restored");lib.RestoreKnowledge(legacy,legacyTarget,root,root,CancellationToken.None);check(new Library(legacyTarget).Find(pdfItem.id).path==pdf,"legacy v1 archives retain explicit old/new absolute root mapping support");
  string nested=Path.Combine(root,"public-tree","nested");Directory.CreateDirectory(nested);string nestedFile=Path.Combine(nested,"external.txt");File.WriteAllText(nestedFile,"NESTED_REFERENCE_CANARY");lib.Import(new[]{nestedFile},null);string nestedArchive=Path.Combine(root,"nested.koklib");lib.ExportKnowledge(nestedArchive,false,CancellationToken.None,Path.Combine(root,"public-tree"));string nestedTarget=Path.Combine(root,"nested-restored");lib.RestoreKnowledge(nestedArchive,nestedTarget,"",Path.Combine(root,"public-tree"),CancellationToken.None);check(new Library(nestedTarget).Db.items.Any(e=>e.path==nestedFile),"explicit relative roots preserve nested reference mapping without serializing the root");lib.Remove(lib.Db.items.Single(e=>e.path==nestedFile).id);
  string traversal=Path.Combine(root,"traversal.koklib");using(var input=ZipFile.OpenRead(refs))using(var output=ZipFile.Open(traversal,ZipArchiveMode.Create)){foreach(var entry in input.Entries){using(var stream=output.CreateEntry(entry.FullName).Open()){if(entry.FullName=="manifest.json"){PortableLibrary data;using(var r=new StreamReader(entry.Open()))data=Library.Json.Deserialize<PortableLibrary>(r.ReadToEnd());data.items.First(e=>e.id==pdfItem.id).path="../outside.pdf";var bytes=Encoding.UTF8.GetBytes(Library.Json.Serialize(data));stream.Write(bytes,0,bytes.Length);}else using(var source=entry.Open())source.CopyTo(stream);}}}Reject(()=>lib.PreviewKnowledgeRestore(traversal),check,"portable v2 refuses relative traversal before restoration");
  string target=Path.Combine(root,"restored");lib.RestoreKnowledge(archive,target,"","",CancellationToken.None);var restored=new Library(target);check(restored.Db.items.Select(e=>e.id).OrderBy(x=>x).SequenceEqual(lib.Db.items.Select(e=>e.id).OrderBy(x=>x)),"portable restore preserves stable source identities");check(restored.Db.workspace.clips.Single().source.start==2&&restored.Db.workspace.spaces.Single().members.Contains(clip.id),"portable restore preserves Clip coordinates and Space relations");check(restored.DocumentSource(camera.id).text==lib.DocumentSource(camera.id).text,"restored managed documents retain editable content");check(restored.Db.settings.Count==1&&!restored.Db.settings.ContainsKey("agentToolReceipts"),"portable exports restore without provider credentials or Agent private state");Reject(()=>lib.RestoreKnowledge(archive,target,"","",CancellationToken.None),check,"restore refuses to overwrite an existing directory");
  string bad=Path.Combine(root,"bad.koklib");using(var source=ZipFile.OpenRead(archive))using(var output=ZipFile.Open(bad,ZipArchiveMode.Create)){foreach(var entry in source.Entries){using(var input=entry.Open())using(var stream=output.CreateEntry(entry.FullName).Open()){if(entry.FullName.StartsWith("sources/")){var bytes=Encoding.UTF8.GetBytes("tampered");stream.Write(bytes,0,bytes.Length);}else input.CopyTo(stream);}}}string badTarget=Path.Combine(root,"bad-restore");Reject(()=>lib.RestoreKnowledge(bad,badTarget,"","",CancellationToken.None),check,"restore verifies attachment size and checksum");check(!Directory.Exists(badTarget)&&!Directory.GetDirectories(root,"bad-restore.restore-*").Any(),"failed restore removes only its isolated staging directory");
  var capture=new CaptureRequest{title="网页摘录",url="https://example.org/article",text="CAPTURE_TEXT_CANARY"};Entry captured=lib.CaptureSource(capture),again=lib.CaptureSource(capture);check(captured.id==again.id&&captured.sourceInfo.url==capture.url,"repeated captures deduplicate by payload and retain source URL");check(File.ReadAllText(captured.path).Contains(capture.text),"captured text becomes an offline editable Markdown source");Reject(()=>lib.CaptureSource(new CaptureRequest{url="file:///C:/private.txt",text="bad"}),check,"capture rejects local-file URLs supplied by external callers");
  string renamed=Path.Combine(root,"moved.md");File.Copy(captured.path,renamed);string before=lib.ContentStamp(captured.id);var relink=lib.ProposeRelink(captured.id,renamed,before);check(lib.Find(captured.id).path!=renamed,"relinking creates a reviewable proposal before changing paths");new Operations(lib,null).Apply(relink.id);check(lib.Find(captured.id).path==renamed,"approved relinking retains the source identity");new Operations(lib,null).Undo(relink.id);check(lib.Find(captured.id).path==captured.path,"relink undo restores the previous source path");
 }
}
